cypher:
MATCH (m:Movie {title:'Avatar'})
CALL (m) {
  WITH m
  MATCH (u:User)-[r:RATED]->(m)
  RETURN avg(r.rating) AS avgRating, collect(u.name) AS raters
}
RETURN m.title AS movie, avgRating, raters;

